# Inspect only compressed test data emitted through the CLI.
class Bits:
 def __init__(self,data):self.data=data;self.pos=0
 def read(self,n):
  v=0
  for k in range(n):v|=((self.data[self.pos//8]>>(self.pos%8))&1)<<k;self.pos+=1
  return v
 def tree(self,lens):
  counts=[lens.count(i) for i in range(16)];counts[0]=0;c=0;nexts=[0]*16;out={}
  for n in range(1,16):c=(c+counts[n-1])*2;nexts[n]=c
  for val,n in enumerate(lens):
   if n:out[n,nexts[n]]=val;nexts[n]+=1
  return out
 def sym(self,t):
  c=0
  for n in range(1,16):
   c=c*2+self.read(1)
   if (n,c) in t:return t[n,c]
  raise ValueError('bad code')
def scan(data):
 b=Bits(data);out=[];at=0
 lensbase=[3,4,5,6,7,8,9,10,11,13,15,17,19,23,27,31,35,43,51,59,67,83,99,115,131,163,195,227,258]
 lensex=[0]*8+[1]*4+[2]*4+[3]*4+[4]*4+[5]*4+[0]
 distex=[0]*4+sum(([i]*2 for i in range(1,14)),[])
 while True:
  start=b.pos;last=b.read(1);typ=b.read(2);begin=at
  if typ==0:
   b.pos=(b.pos+7)//8*8;ln=b.read(16);neg=b.read(16);assert ln^neg==65535;b.pos+=ln*8;at+=ln
  else:
   if typ==1:ll=[8]*144+[9]*112+[7]*24+[8]*8;dd=[5]*32
   elif typ==2:
    nl=b.read(5)+257;nd=b.read(5)+1;nc=b.read(4)+4
    order=[16,17,18,0,8,7,9,6,10,5,11,4,12,3,13,2,14,1,15];cl=[0]*19
    for i in range(nc):cl[order[i]]=b.read(3)
    t=b.tree(cl);ls=[]
    while len(ls)<nl+nd:
     s=b.sym(t)
     if s<16:ls.append(s)
     elif s==16:ls.extend([ls[-1]]*(b.read(2)+3))
     elif s==17:ls.extend([0]*(b.read(3)+3))
     else:ls.extend([0]*(b.read(7)+11))
    ll=ls[:nl];dd=ls[nl:]
   else:raise ValueError('reserved block type')
   lt=b.tree(ll);dt=b.tree(dd)
   while True:
    s=b.sym(lt)
    if s<256:at+=1
    elif s==256:break
    else:
     at+=lensbase[s-257]+b.read(lensex[s-257]);d=b.sym(dt);b.read(distex[d])
  out.append((start,b.pos,last,typ,begin,at))
  if last:break
 return out
if __name__=='__main__':
 import subprocess,random,zlib
 r=random.Random(123);d=bytes(r.randrange(32,127) for _ in range(100000))
