        }
        else shortopts=s.substr(1);
        for (size_t j=0;j<shortopts.size();++j) {
            char c=shortopts[j];
            if (c>='0'&&c<='9') {
                unsigned n=0;
                do {n=std::min<unsigned>(100,n*10+shortopts[j]-'0');++j;}
                while(j<shortopts.size() && std::isdigit(static_cast<unsigned char>(shortopts[j])));
