void environment(const char* name) {
    const char* v=std::getenv(name);if(!v)return;
    std::vector<std::string> tokens;
    while(*v) {
        while(*v&&std::isspace(static_cast<unsigned char>(*v)))++v;
        const char* start=v;
        while(*v&&!std::isspace(static_cast<unsigned char>(*v)))++v;
        if(v>start)tokens.emplace_back(start,v-start);
    }
    parse(tokens,name);
}
Bytes read_all(int fd,const std::string& name) {
    Bytes out;std::array<unsigned char,131072> buf;
    for(;;) {
        ssize_t n=::read(fd,buf.data(),buf.size());
        if(n<0) {if(errno==EINTR)continue;int e=errno;fatal("read error on "+name+" ("+system_error(e)+")",e);}
        if(!n)break;
        out.insert(out.end(),buf.begin(),buf.begin()+n);
    }
    return out;
}
void write_all(int fd,const Bytes& b,const std::string& name) {
    for(size_t p=0;p<b.size();) {
        ssize_t n=::write(fd,b.data()+p,std::min<size_t>(b.size()-p,1u<<30));
        if(n<0) {if(errno==EINTR)continue;int e=errno;fatal("write error on "+name+" ("+system_error(e)+")",e);}
        if(!n)fatal("write error on "+name+" (No space left on device)",ENOSPC);
        p+=n;
    }
}

