        for(int i=1;i<argc;++i)args.emplace_back(argv[i]);
        parse(args);
        if(opt.name==-1)opt.name=!opt.decompress;
        if(opt.time==-1)opt.time=!opt.decompress;
        if(files.empty())files.push_back({"-",true});
        for(auto& file:files)process_file(file);
